#!/usr/bin/env python3
"""Writes design_notes.json for the SIM-032 phase-2 activetether build from results.json (numbers) plus the
design decisions / conflict resolutions (text). Evidence: numerical-uncalibrated simulation; nothing built or tested."""
import json, os
here = os.path.dirname(os.path.abspath(__file__))
R = json.load(open(os.path.join(here, 'results.json')))
E, V, S, Rb = R['ensemble'], R['variants'], R['sensitivity'], R['robustness']
J = E['judged']
st = E['stats']
r3 = lambda x: None if x is None else round(x, 2)
def js(k): return {kk: r3(v['value']) for kk, v in V[k]['judged'].items()}

notes = {
  'id': 'SIM-032 phase 2 activetether design notes', 'date': R['generated'],
  'evidence': 'Numerical-uncalibrated simulation (sim/js/concepts/activetether) + catalogue numbers from the phase-1 reports. NOTHING was built, flown or measured. M-070 not_run, G-MATURE closed. Simulation is not verification.',
  'architecture': {
    'summary': 'AT-1: lumbar back unit (MN3110 700 Kv reel, 2:1 belt, yo-yo drum 25 m of 0.36 mm UHMWPE, slip clutch 35 N, ratchet, metering head with tension flexure, 2-axis exit line-angle gimbal, 4S1P P28A, MCU/IMU/GNSS/baro/radio, cutter, 38 N weak link at the exit) with a hinged 0.55 m "scorpion quiver" that is the dock, launch rail and line exit (0.66 m behind / 0.10 m below the pelvis); flyer = 116 g folding umbrella delta (0.094 m², L/D 5.9 ASSUMED polar) with pitot + AoA vane + IMU/GNSS/UWB, two flight servos (bridle pitch / roll), airbrake flaps, 1S 450 mAh cell, 4K-class gyro-EIS camera on a 2-servo pan/tilt mount (48 MP 66° module ASSUMED as default sensor).',
    'modes': 'STOWED → (detector start) DEPLOY 1.3 s → READY → (straight glide ≥0.6 s, apparent wind along travel ≥1.35·Vstall on windEstimate + GNSS, tail component ≤3 m/s) LAUNCH (rail release 0.45 m behind the mouth, drift-back pay-out ramp ≤2 m/s to 2.5 m, then tension-controlled to 6 m) → FLY (glide-ratio servo at 50°, roll loop, kite-like length adaptation) → stop: BRAKE (deep stall, slack take-up ≤1 m/s, side-drop in tailwind) → LANDED → RETRIEVE (flagged wing, 3 m/s, 1.5 m/s in the last 3 m; towed at 4 m while still riding) or FLYIN (wind holds it up, flyer behind the rider) → CAPTURE (0.3 m/s, hold while the flyer moves, quiver aligns to the UWB/angle estimate, ASSUMED capture model) → DOCKED → STOWED; ABORT on a detected fall (deep stall, free-spool, cutter at 15 N or a closing flyer); MANUAL stow after 3 missed captures (20 s, +1 op).',
  },
  'decisions': [
    {'decision': 'Reel in the lumbar back unit, never on the flyer', 'drivenBy': 'aero H5 (flyer reel → 156–186 g, KE over the cap), engineering B rejected (≈0.20 kg flyer, 12.2 m/s KE cap)', 'numbers': {'flyerKg': R['design']['flyers']['delta']['fly']['kg'], 'keCapSpeed_ms': r3(R['design']['flyers']['delta']['keCapSpeedCam'])}},
    {'decision': 'The reel does not chase tension; it holds length, takes up slack, adapts length slowly (pay out on surplus lift, reel in on a pitot lift deficit, KE-governed), tows and retrieves', 'drivenBy': 'aero H3, control H3/H4; user direction "fly it like a kite" kept as the slow length law', 'numbers': {'reelEnergyWhPerRun_p50': r3(st['reelWh']['p50']), 'reelPeakW_p90': r3(st['reelPeakW']['p90'])}},
    {'decision': 'Elevation held by a glide-ratio servo (airbrake first, then lower CL when the brake saturates)', 'drivenBy': 'aero H9 (fly braked), control physics finding (slope tilts the window forward: 50° above the horizon needs L/D_eff ≈0.7)', 'numbers': {'elevMedianFLY_p50_deg': r3(st['elevMed']['p50']), 'tensionMedian_p50_N': r3(st['tensionMed']['p50'])}},
    {'decision': 'Station defined relative to the exit (devK = 0), not on the mean course', 'drivenBy': 'this build: the shared carving rider swings the pack ±8 m per turn; holding the mean course needs ±5 m of reel stroke per turn and was less stable (sensitivity station_meancourse_0_5)', 'numbers': {'devK0.5': {k: r3(v['value']) for k, v in S['station_meancourse_0_5']['judged'].items() if k in ('avail', 'keMax', 'headClear')}}},
    {'decision': 'Filming line 10 m (not 7.5 m)', 'drivenBy': 'this build: at 7.5 m the carving swing whips the flyer (more snow contacts and KE); 10 m low-passes it at the cost of bodyPx', 'numbers': {'line_7_5': {k: r3(v['value']) for k, v in S['line_7_5']['judged'].items() if k in ('avail', 'keMax', 'headClear', 'pxMed')}, 'line_13': {k: r3(v['value']) for k, v in S['line_13']['judged'].items() if k in ('avail', 'keMax', 'headClear', 'pxMed')}}},
    {'decision': 'Low apparent wind is a gate: no launch with tail component >3 m/s (windEstimate) or apparent wind along travel <1.35·Vstall; in-flight lift margin <1.15 for 2 s → brake and retrieve', 'drivenBy': 'consensus 3 (aero H2/H11, control H6/H7), towglider tail lesson', 'numbers': {'casesNeverFlown': 48 - E['counts']['flown']}},
    {'decision': 'Stops: deep stall + slack take-up only (never fast reel-in); side-drop first in tailwind; fly-in only while the flyer is behind the rider', 'drivenBy': 'aero H11 (fast reel-in 38–145 J), control H8', 'numbers': {'dockTime': st.get('dockTime')}},
    {'decision': 'Launch only on a straight glide from a 0.45 m rail release with a drift-back pay-out ramp', 'drivenBy': 'control H6 (whip below 5 m while carving), engineering spring launch', 'numbers': {'launchSuccess_mean': r3(st['launchSuccess']['mean'])}},
    {'decision': 'Lumbar exit 0.66 m behind the pelvis', 'drivenBy': 'engineering headClearance table (lumbar 0.55 m ≥1.0 m up to 55°), aero H1', 'numbers': {'exitToHelmet_m': 1.24}},
    {'decision': 'Camera on the flyer (delta) chosen over the line pod and the low-wing-loading kite', 'drivenBy': 'variant study below', 'numbers': {k: js(k) for k in V}},
    {'decision': 'Safety hardware: 38 N weak link at the exit, 35 N slip clutch, cutter, ratchet, KE governor on reel-in', 'drivenBy': 'consensus 7, engineering brake_clutch_cut, product REG-D3/D4', 'numbers': {'bodyForcePeak_max_N': r3(J['bodyForcePeak']['value']), 'casesWeakLinkOrCut': E['counts'].get('broke', 0) + E['counts'].get('cut', 0)}},
  ],
  'conflictResolutions': {
    'KE': {'question': 'control H11 median 32 J vs aero H4 worst 13 J at 130 g', 'answer': f"With the pendulum/roll dynamics modelled the 116 g delta reaches KE max {r3(J['keMax']['value'])} J (p50 {r3(st['keMax']['p50'])} J, p90 {r3(st['keMax']['p90'])} J) — the control scientist's side was right: the floor ½·m·v_rider² is already ≈10–14 J at 13–15 m/s and swings add 3–6 m/s. Mass sensitivity: ×0.7 → {r3(S['mass_x0_7']['judged']['keMax']['value'])} J, ×0.5 (58 g) → {r3(S['mass_x0_5']['judged']['keMax']['value'])} J (keMax judged as max over 48).", 'verdict': 'FAIL at 116 g; see mass envelope'},
    'headClearClosedLoop': {'question': 'control H10 0.01–0.08 m vs engineering ≥1.0 m up to 55°', 'answer': f"In steady braked flight the lumbar exit gives ≥1.0 m (line passes ≈1.06–1.2 m from the helmet at 45–60°), but the 48-case minimum is {r3(J['headClear']['value'])} m (p10 {r3(st['headClear']['p10'])} m): the lows occur in tail/cross-wind stops (brake/fly-in/tow-in phases), not in filming flight.", 'verdict': 'engineering right for flight, control right for the full run: FAIL'},
    'launchFromBack': {'question': 'control H6 whip vs engineering spring launch', 'answer': f"Straight-glide-only launch with a 0.45 m rail release and a ≤2 m/s drift-back ramp succeeds in {r3(st['launchSuccess']['mean'])} % of attempts (mean over launched cases); launches are refused when the turns start before the gate opens. ≤2 m/s is slow: 4 m/s sensitivity avail {r3(S['launch_payout_4']['judged']['avail']['value'])} %.", 'verdict': 'conditional'},
    'dockArrival': {'question': 'glider 5.1 m/s vs kite 1.6 m/s vs engineering 60–96 %', 'answer': f"Landing behind and towing in at 0.3 m/s with a settle-hold gives capture arrival p50 {r3(st['capVrel'].get('p50'))} / p90 {r3(st['capVrel'].get('p90'))} m/s and first-try dock success {r3(st['dockFirstTry']['mean'])} % (ASSUMED capture model), dock time p50/p90 {r3(st['dockTime'].get('p50'))}/{r3(st['dockTime'].get('p90'))} s.", 'verdict': 'arrival speed solved by land-and-tow; first-try ≥98 % and p90 ≤10 s not met'},
    'flyerType': {'question': 'folding delta vs low-wing-loading kite', 'answer': f"Kite (0.30 m², 139 g with camera) launches at lower speed but its large area at 12–20 m/s gives tension spikes, weak-link breaks and KE {r3(V['kite_fly']['judged']['keMax']['value'])} J; avail {r3(V['kite_fly']['judged']['avail']['value'])} % vs delta {r3(V['delta_fly']['judged']['avail']['value'])} %.", 'verdict': 'delta'},
    'camera': {'question': 'on the flyer vs clamped on the line 5–6 m from the exit', 'answer': f"The line pod (72 g) sits on the segment that swings with the carving exit (±8 m) and adds a second node: avail {r3(V['delta_line']['judged']['avail']['value'])} %, jitter p90 {r3(V['delta_line']['judged']['jitterRms']['value'])} °/s, and a two-stage dock (pod first) — worse than on the flyer ({r3(V['delta_fly']['judged']['avail']['value'])} %, {r3(V['delta_fly']['judged']['jitterRms']['value'])} °/s).", 'verdict': 'camera on the flyer'},
    'clothesline': {'question': 'line low behind the rider', 'answer': f"A lumbar exit at ≈0.8 m height always leaves the first ≈{r3(st['lowLenP90']['p50'])} m behind the quiver below 1.8 m (share of airborne riding time {r3(st['lowLineShare']['mean'])} %); third-party exposure p50 {r3(st['thirdPartyS']['p50'])} s per run. Head clearance (low/rear exit) and the clothesline (high exit) conflict geometrically.", 'verdict': 'FAIL (product target 0)'},
  },
  'bomMassPower': {'flyer_g': R['design']['flyers']['delta']['fly'], 'worn': R['design']['worn']['delta_fly'], 'adjustmentsVsEngineering': ['+2 g pitot/vane and +2.5 g pan servo on the flyer (116 g vs engineering 111 g)', 'battery energy on the shared 150 Wh/kg basis (32 Wh) instead of the cell rating (40 Wh)', '48 MP 66° camera module ASSUMED with the 27 g cam4kNoGimbal mass', 'kite variant: Ø64 × 0.55 m quiver (2.9 L), 139 g with camera'], 'meanPowerW_p50': r3(st['meanW']['p50']), 'endurance_min_min': r3(J['endurance']['value'])},
  'killTests': ['Tow-rig polar of the folding delta: kill if ε cannot be held 40–55° with T ≥1.5 N (engineering R6)', '50 captures at −10 °C in the quiver from snow tow-in: kill if <95 % first time (engineering R3, towglider audit)', 'Flight on a carving dummy/rider rig: kill if snow contacts >1 per run or KE >14.9 J at ≥12 m/s with a ≤0.12 kg flyer', 'Short-line launch from a moving pack (straight glide): kill if <95 % reach 6 m without snow contact', 'Weak-link/cutter bench: kill if line force on the body exceeds 40 N (50 ms) in snag/fall tests', 'Head-clearance dummy (tail/cross 3–9 m/s stops): kill if any line/flyer passes <1.0 m from the helmet', 'Lift/queue/bus IMU log replay (≥500 lift rides): kill if any launch on a lift'],
}
json.dump(notes, open(os.path.join(here, 'design_notes.json'), 'w'), indent=1, ensure_ascii=False)
print('ok')
